using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using Bokumyaku.Presentation;using Bokumyaku.Presentation.Drawing;using ConnectPiece.SumiEngine.Core;
public static class RootPigmentCheck {
 public static object Before()=>Capture(false);
 public static object After()=>Capture(true);
 static object Capture(bool after){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-")||g.PaintedBranchCount!=g.Run.Branches.Count)throw new Exception("Incomplete isolated fixture");var flags=BindingFlags.NonPublic|BindingFlags.Instance;var surface=(DirtyInkSurface)typeof(BokumyakuGame).GetField("persistentInk",flags).GetValue(g);var core=(SumiEngineCore)typeof(DirtyInkSurface).GetField("core",flags).GetValue(surface);byte[] data;using(var stream=new MemoryStream()){using(var writer=new BinaryWriter(stream)){for(int y=0;y<surface.Height;y++)for(int x=0;x<surface.Width;x++)writer.Write(core.Paper.PigmentAt(x,y));data=stream.ToArray();}}string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(data)).Replace("-","");if(!after)SessionState.SetString("RootPigment.baseline",hash);else if(hash!=SessionState.GetString("RootPigment.baseline",""))throw new Exception("Final pigment changed");var report=new{after,hash,width=surface.Width,height=surface.Height,rootSlices=g.PaintedRootSlices,branches=g.PaintedBranchCount,method="Exact float pigment bytes in paused seed42 900tick fixture"};File.WriteAllText(Path.GetFullPath("../docs/evidence/root-pigment-"+(after?"after":"before")+".json"),Newtonsoft.Json.JsonConvert.SerializeObject(report));return report;
 }
}
